// ---- src/services/course-deduplication.js ----
function mergeUniqueCourseValues(...valueLists) {
  const seen = new Set();
  const merged = [];

  valueLists.flat().forEach((value) => {
    const normalized = String(value || "").trim();
    if (!normalized) {
      return;
    }

    const key = normalized.toLowerCase();
    if (seen.has(key)) {
      return;
    }

    seen.add(key);
    merged.push(normalized);
  });

  return merged;
}

function getCourseRecordCompletenessScore(course = {}) {
  return Number(course?.metadata?.completenessScore || 0);
}

function getCanonicalCourseDedupeKey(course = {}) {
  const providerCourseId = String(course?.metadata?.providerCourseId || "").trim();
  if (providerCourseId) {
    return `${course?.providerId || ""}:${providerCourseId}`;
  }

  const slug = String(course?.slug || course?.id || "").trim().toLowerCase();
  const city = String(course?.city || "").trim().toLowerCase();
  const state = String(course?.state || "").trim().toLowerCase();
  return `${slug}:${city}:${state}`;
}
function mergeCanonicalCourseRecords(primary = {}, secondary = {}) {
  const primaryScore = getCourseRecordCompletenessScore(primary);
  const secondaryScore = getCourseRecordCompletenessScore(secondary);
  const preferred = primaryScore >= secondaryScore ? primary : secondary;
  const fallback = preferred === primary ? secondary : primary;

  return {
    ...fallback,
    ...preferred,
    aliases: mergeUniqueCourseValues(primary?.aliases || [], secondary?.aliases || []),
    searchKeywords: mergeUniqueCourseValues(primary?.searchKeywords || [], secondary?.searchKeywords || []),
    teeBoxes: Array.isArray(preferred?.teeBoxes) && preferred.teeBoxes.length
      ? preferred.teeBoxes
      : (Array.isArray(fallback?.teeBoxes) ? fallback.teeBoxes : []),
    metadata: {
      ...(fallback?.metadata || {}),
      ...(preferred?.metadata || {}),
      aliases: mergeUniqueCourseValues(primary?.metadata?.aliases || [], secondary?.metadata?.aliases || []),
      keywords: mergeUniqueCourseValues(primary?.metadata?.keywords || [], secondary?.metadata?.keywords || []),
      sourceHistory: mergeUniqueCourseValues(
        primary?.metadata?.sourceHistory || [],
        secondary?.metadata?.sourceHistory || [],
        [primary?.metadata?.source || ""],
        [secondary?.metadata?.source || ""]
      ),
      completenessScore: Math.max(primaryScore, secondaryScore),
    },
  };
}
function dedupeCanonicalCourseRecords(records = []) {
  const deduped = new Map();

  records.forEach((record) => {
    const key = getCanonicalCourseDedupeKey(record);
    const existing = deduped.get(key);
    deduped.set(key, existing ? mergeCanonicalCourseRecords(existing, record) : record);
  });

  return [...deduped.values()];
}

// ---- src/state/persistence.js ----
const LIVE_SYNC_RENDER_REASONS = [
  "realtime-member-state",
  "realtime-round-event",
  "realtime-round-snapshot",
];

function getAvailableStorage() {
  try {
    if (typeof localStorage === "undefined") {
      return null;
    }

    return localStorage;
  } catch (error) {
    console.warn("[Golfers Nation] Local storage is unavailable.", error);
    return null;
  }
}function loadPersistedState(createDefaultState) {
  const fallback = createDefaultState();
  const storage = getAvailableStorage();
  if (!storage) {
    return fallback;
  }

  try {
    const saved = storage.getItem(STORAGE_KEY);
    if (!saved) {
      return fallback;
    }

    const parsed = JSON.parse(saved);
    return {
      ...cloneData(fallback),
      ...parsed,
      session: {
        ...fallback.session,
        ...parsed.session,
        cloudSync: {
          ...(fallback.session?.cloudSync || {}),
          ...(parsed.session?.cloudSync || {}),
        },
        nearby: {
          ...(fallback.session?.nearby || {}),
          ...(parsed.session?.nearby || {}),
        },
        spotify: {
          ...(fallback.session?.spotify || {}),
          ...(parsed.session?.spotify || {}),
        },
      },
      auth: { ...(fallback.auth || {}), ...(parsed.auth || {}) },
      social: { ...fallback.social, ...parsed.social },
      gear: { ...fallback.gear, ...parsed.gear },
      currentUser: {
        ...fallback.currentUser,
        ...parsed.currentUser,
        privacy: {
          ...(fallback.currentUser?.privacy || {}),
          ...(parsed.currentUser?.privacy || {}),
        },
        appearance: {
          ...(fallback.currentUser?.appearance || {}),
          ...(parsed.currentUser?.appearance || {}),
        },
        social: {
          ...(fallback.currentUser?.social || {}),
          ...(parsed.currentUser?.social || {}),
          handles: {
            ...(fallback.currentUser?.social?.handles || {}),
            ...(parsed.currentUser?.social?.handles || {}),
          },
        },
        integrations: {
          ...(fallback.currentUser?.integrations || {}),
          ...(parsed.currentUser?.integrations || {}),
          spotify: {
            ...(fallback.currentUser?.integrations?.spotify || {}),
            ...(parsed.currentUser?.integrations?.spotify || {}),
          },
        },
        subscription: {
          ...(fallback.currentUser?.subscription || {}),
          ...(parsed.currentUser?.subscription || {}),
        },
      },
    };
  } catch (error) {
    return fallback;
  }
}function persistAppState(state) {
  const storage = getAvailableStorage();
  if (!storage) {
    return false;
  }

  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(state));
    return true;
  } catch (error) {
    console.warn("[Golfers Nation] State persistence failed.", error);
    return false;
  }
}function persistPlatformState(platform, state) {
  const prepared = platform.data.prepareForPersistence(state);
  platform.data.persist(prepared);
  return prepared;
}function subscribeStorePersistence({
  store,
  platform,
  safeRender,
  applyAppearanceToDocument = () => {},
  applyShellModeToDocument = () => {},
} = {}) {
  return store.subscribe((state, meta = {}) => {
    try {
      persistPlatformState(platform, state);
    } catch (error) {
      console.error("[Golfers Nation] Failed to persist app state.", error);
    }

    if (LIVE_SYNC_RENDER_REASONS.includes(meta.reason)) {
      console.info("[Golfers Nation] Rerender triggered after live sync update.", {
        reason: meta.reason,
        activeRoundId: state.session?.activeRoundId || null,
      });
    }

    safeRender(state, "state-render", meta);
    applyAppearanceToDocument(state);
    applyShellModeToDocument(state);
  });
}function renderInitialAppState({
  store,
  safeRender,
  applyAppearanceToDocument = () => {},
  applyShellModeToDocument = () => {},
} = {}) {
  const state = store.getState();
  if (!safeRender(state, "initial-render", { reason: "initial-render" })) {
    return false;
  }

  applyAppearanceToDocument(state);
  applyShellModeToDocument(state);
  return true;
}

// ---- src/state/store.js ----
function createStore(initialState) {
  let state = cloneData(initialState);
  const listeners = new Set();

  function getState() {
    return state;
  }

  function setState(updater, meta = {}) {
    const draft = cloneData(state);
    const nextState = typeof updater === "function" ? updater(draft) || draft : updater;
    state = nextState;
    listeners.forEach((listener) => listener(state, meta));
  }

  function subscribe(listener) {
    listeners.add(listener);
    return () => listeners.delete(listener);
  }

  return {
    getState,
    setState,
    subscribe,
  };
}

