    roundId: round.id,
    title: `${round.courseName} live round`,
    inviteCode: normalizedInviteCode,
    status: "active",
    transport: round.sync?.transport || "cloud",
    hostUserId: round.players?.[0]?.userId || null,
    createdAt: round.createdAt || Date.now(),
