  const next = cloneData(overrides || {});
  const followedProfileIds = Array.isArray(next.followedProfileIds)
    ? [...new Set(next.followedProfileIds.filter(Boolean))]
    : [];
  const friendProfileIds = Array.isArray(next.friendProfileIds)
